/* Shared visual language for the separately embedded movement activity. */
(()=>{'use strict';const $=id=>document.getElementById(id),T=(a,b)=>document.documentElement.lang.startsWith('zh')?b:a;
const symbols={pause:'Ⅱ',play:'▶',settings:'⚙',language:'文/A',home:'⌂',back:'←',close:'×',reset:'↻',next:'→',skip:'⇥',sound:'♫',grid:'▦',hint:'💡'};
function art(kind){try{if(parent!==window&&parent.MindGardenGameUI)return parent.MindGardenGameUI.icon(kind)}catch{}return '<span aria-hidden="true">'+symbols[kind]+'</span>'}
function decorate(b,kind,label){if(!b)return;const key=kind+'|'+label;if(b.dataset.utility!==key){b.dataset.utility=key;b.innerHTML=art(kind)}b.setAttribute('aria-label',label);b.title=label;b.classList.add('movement-icon');b.classList.toggle('movement-hint',kind==='hint');}
const allowed=new WeakSet();let confirming=false;
function confirm(message,run){if(confirming)return;confirming=true;const d=document.createElement('dialog');d.className='movement-confirm';d.innerHTML='<h2>'+T('Please confirm','请确认')+'</h2><p>'+message+'</p><div><button id="movementStay"></button><button id="movementConfirm"></button></div>';document.body.append(d);decorate($('movementStay'),'close',T('Cancel — keep playing','取消 — 继续游戏'));decorate($('movementConfirm'),'next',T('Confirm','确认'));const done=()=>{d.close?.();d.remove();confirming=false};d.oncancel=e=>{e.preventDefault();done()};$('movementStay').onclick=done;$('movementConfirm').onclick=()=>{done();run()};if(d.showModal)d.showModal();else d.setAttribute('open','');$('movementStay').focus();}
function mount(){const header=document.querySelector('header'),footer=$('footer');if(!header||!footer)return;decorate($('brand'),'home',T('Home','主页'));const pause=$('pause');if(pause){const resume=/Resume|继续/.test(pause.textContent)||pause.dataset.utility?.startsWith('play|');decorate(pause,resume?'play':'pause',T(resume?'Resume':'Pause',resume?'继续':'暂停'));if(pause.parentElement!==header)header.append(pause)}
const map={repeat:['hint','Hint — repeat instruction','提示 — 重复指令'],again:['hint','Hint — show again','提示 — 再示范一次'],skip:['skip','Skip movement','跳过动作'],finish:['close','Finish activity','结束活动'],next:['next','Continue','继续'],done:['next','Finished','已完成'],replay:['reset','Replay','重玩'],nextLevel:['next','Next level','下一关'],restart:['settings','Settings','设置'],resultPause:['pause','Take a break','休息一下'],resultHome:['home','Home','主页'],resultGames:['grid','Games','游戏'],resultBack:['back','Back','返回'],resultResume:['play','Resume','继续'],resultSetupBack:['back','Back','返回'],voice:['sound','Voice','语音']};for(const [id,[kind,en,zh]]of Object.entries(map))decorate($(id),kind,T(en,zh));
const stages=$('stages');if(stages&&stages.parentElement!==footer)footer.prepend(stages);let gear=$('movementSettings');if(!gear){gear=document.createElement('button');gear.id='movementSettings';decorate(gear,'settings',T('Settings','设置'));footer.append(gear);gear.onclick=()=>{const lang=$('language'),voice=$('voice');if(lang)lang.hidden=!lang.hidden;if(voice)voice.hidden=!voice.hidden;};}
const language=$('language');if(language&&language.parentElement!==footer){footer.append(language);language.hidden=true;}if(language)decorate(language,'language',T('Language: English / Chinese','语言：英文 / 中文'));const voice=$('voice');if(voice&&voice.parentElement!==footer){footer.append(voice);voice.hidden=true;}
}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b||b.closest('dialog'))return;if(allowed.has(b)){allowed.delete(b);return;}if(b.matches('#brand,#resultHome,#resultGames,#resultBack,#resultSetupBack')){e.preventDefault();e.stopImmediatePropagation();const pause=$('pause');if(pause&&pause.dataset.utility?.startsWith('pause|'))pause.click();confirm(T('Leave this screen? Your unfinished activity will end.','离开此页面？尚未完成的活动将结束。'),()=>{allowed.add(b);b.click()});}},true);
new MutationObserver(mount).observe(document.body,{childList:true,subtree:true});mount();
})();
